"""MedMind — massive content seeder.
Fills all empty specialties with modules, lessons, MCQs, flashcards and courses.
Run from host: python3 /opt/medmind/seed_content_massive.py
"""
import json, uuid, logging, sys
import psycopg2, psycopg2.extras

DB = "host=172.18.0.2 port=5432 dbname=medmind user=medmind password=medmind_secret"
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s",
                    handlers=[logging.StreamHandler(sys.stdout),
                              logging.FileHandler("/tmp/seed_content.log","w")])
log = logging.getLogger()

# ── helpers ───────────────────────────────────────────────────────────────────
def uid(): return str(uuid.uuid4())

def get_conn():
    return psycopg2.connect(DB)

def insert_module(cur, specialty_id, mod_def, order_idx=0):
    mid = uid()
    is_vet = specialty_id and mod_def.get("code", "").startswith("VET_")
    hours = round(mod_def.get("minutes", 90) / 60, 1)
    cur.execute("""
        INSERT INTO modules(id,specialty_id,title,description,code,
            level_label,is_published,module_order,duration_hours,is_veterinary,created_at,updated_at)
        VALUES(%s,%s,%s,%s,%s,%s,true,%s,%s,%s,NOW(),NOW())
        ON CONFLICT(code) DO UPDATE SET is_published=true,title=EXCLUDED.title RETURNING id
    """, (mid, specialty_id, mod_def["title"], mod_def.get("desc",""),
          mod_def["code"], mod_def.get("level","beginner"),
          order_idx, hours, is_vet))
    row = cur.fetchone()
    return row[0] if row else None

def insert_lesson(cur, module_id, lesson_def, order_idx=0):
    cur.execute("""
        INSERT INTO lessons(id,module_id,title,lesson_code,lesson_order,content,
            estimated_minutes,status,created_at,updated_at)
        VALUES(%s,%s,%s,%s,%s,%s::jsonb,%s,'published',NOW(),NOW())
    """, (uid(), module_id, lesson_def["title"], lesson_def["code"],
          order_idx, json.dumps(lesson_def.get("content",{}), ensure_ascii=False), 20))

def insert_mcq(cur, module_id, mcq_def):
    cur.execute("""
        INSERT INTO mcq_questions(id,module_id,question,options,correct,explanation,difficulty,tags,created_at)
        VALUES(%s,%s,%s,%s::jsonb,%s,%s,'medium','{}'::text[],NOW())
    """, (uid(), module_id, mcq_def["q"],
          json.dumps(mcq_def["opts"], ensure_ascii=False),
          mcq_def["ans"], mcq_def.get("exp","")))

def insert_card(cur, module_id, card_def):
    cur.execute("""
        INSERT INTO flashcards(id,module_id,question,answer,difficulty,category,tags,created_at)
        VALUES(%s,%s,%s,%s,'medium','','{}'::text[],NOW())
    """, (uid(), module_id, card_def["q"], card_def["a"]))


