# ════════════ MAIN ════════════════════════════════════════════════════════

def main():
    conn = get_conn()
    cur = conn.cursor()

    # Fetch specialty id map: code -> id
    cur.execute("SELECT id, code FROM specialties")
    spec_map = {row[1]: row[0] for row in cur.fetchall()}
    print(f"Found {len(spec_map)} specialties: {list(spec_map.keys())}")

    total_modules = total_lessons = total_mcqs = total_cards = 0

    for spec_code, data in CONTENT.items():
        spec_id = spec_map.get(spec_code)
        if not spec_id:
            print(f"  [SKIP] specialty '{spec_code}' not found in DB")
            continue

        print(f"\n=== {spec_code} (id={spec_id}) ===")
        for mod_def in data["modules"]:
            mod_id = insert_module(cur, spec_id, mod_def)
            total_modules += 1

            for lesson_def in mod_def.get("lessons", []):
                insert_lesson(cur, mod_id, lesson_def)
                total_lessons += 1

            for mcq_def in mod_def.get("mcqs", []):
                insert_mcq(cur, mod_id, mcq_def)
                total_mcqs += 1

            for card_def in mod_def.get("flashcards", []):
                insert_card(cur, mod_id, card_def)
                total_cards += 1

        conn.commit()
        print(f"  committed {spec_code}")

    cur.close()
    conn.close()
    print(f"\n✅ Done! Inserted: {total_modules} modules, {total_lessons} lessons, {total_mcqs} MCQs, {total_cards} flashcards")

if __name__ == "__main__":
    main()
